                install_extra_registry_skill_source(
                    &source,
                    &skills_path,
                    config.skills.allow_scripts,
                    workspace_dir,
                    &config.skills.extra_registries,
                    no_tier_banner,
                )
                .with_context(|| {
                    get_required_cli_string_with_args(
                        "cli-skills-install-extra-registry-failed",
                        &[("source", &source)],
